import openpyxl
wb = openpyxl.load_workbook('init.xlsx')
ws = wb['Datensatz']
def col(p): return 3+p
def row(c): return 4+c
# total customers with product i>0
def count_i(i):
    c=0
    for r in range(4,34):
        if ws.cell(r,col(i)).value>0: c+=1
    return c
# both i and j
def both(i,j):
    c=0
    for r in range(4,34):
        if ws.cell(r,col(i)).value>0 and ws.cell(r,col(j)).value>0: c+=1
    return c
for i in range(1,9):
    for j in range(1,9):
        if i==j:
            print(i,j,1.0)
        else:
            print(i,j, both(i,j)/count_i(i))
"

